Sure, here's an example code for a Node.js web app with support for serving static files from the /public directory and without requiring a .html extension in the URL:

const express = require('express');
const path = require('path');
const app = express();

// Serve static files from the 'public' directory
app.use(express.static(path.join(__dirname, 'public')));

// Set up a route to serve the homepage
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, 'public/index.html'));
});

// Allow routes without a .html extension to work
app.use((req, res, next) => {
  if (!req.path.includes('.') && req.path !== '/') {
    req.url += '.html';
  }
  next();
});

// Start the server and listen on port 3000
app.listen(3000, () => {
  console.log('Example app listening on port 3000!');
});

In this example, the express.static middleware is used to serve static files from the /public directory, and the path module is used to construct file paths. The route for the homepage sends the index.html file, which is located in the /public directory. The middleware function at the bottom of the code checks whether the requested URL contains a file extension and, if not, adds a .html extension to the URL. This allows URLs without a .html extension to work, as requested.

